package vn.rtr.aeris.mission;
import android.app.Activity;import android.view.*;import android.widget.FrameLayout;import android.graphics.*;import android.os.*;
/** Real touch producer; UI JavaScript cannot fabricate its motion samples. */
public final class FlightPads extends FrameLayout {
 private final NativeInputBridge input;private final Handler ui=new Handler(Looper.getMainLooper());private final Pad left,right;private boolean enabled;private long lastEvent;private volatile long frameAckNs;public long frameAckNs(){return frameAckNs;}private final Choreographer.FrameCallback frame=new Choreographer.FrameCallback(){public void doFrame(long at){if(!enabled)return;frameAckNs=SystemClock.elapsedRealtimeNanos();Choreographer.getInstance().postFrameCallback(this);}};private volatile String layout="{}";public String layoutSnapshot(){return layout;}
 @Override protected void onLayout(boolean changed,int l,int t,int r,int b){super.onLayout(changed,l,t,r,b);int[] a=new int[2],z=new int[2];left.getLocationOnScreen(a);right.getLocationOnScreen(z);layout="{\"observedElapsedNs\":"+SystemClock.elapsedRealtimeNanos()+",\"left\":{\"x\":"+a[0]+",\"y\":"+a[1]+",\"width\":"+left.getWidth()+",\"height\":"+left.getHeight()+"},\"right\":{\"x\":"+z[0]+",\"y\":"+z[1]+",\"width\":"+right.getWidth()+",\"height\":"+right.getHeight()+"}}";}
 public FlightPads(Activity a,NativeInputBridge bridge){super(a);input=bridge;setClipChildren(false);left=new Pad(a,true);right=new Pad(a,false);int size=dp(132);FrameLayout.LayoutParams l=new FrameLayout.LayoutParams(size,size,Gravity.START|Gravity.CENTER_VERTICAL),r=new FrameLayout.LayoutParams(size,size,Gravity.END|Gravity.CENTER_VERTICAL);l.leftMargin=dp(22);r.rightMargin=dp(22);addView(left,l);addView(right,r);setVisibility(GONE);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 public void enabled(boolean value){enabled=value;left.clear();right.clear();setVisibility(value?VISIBLE:GONE);ui.removeCallbacks(sample);Choreographer.getInstance().removeFrameCallback(frame);frameAckNs=0;if(value){Choreographer.getInstance().postFrameCallback(frame);ui.post(sample);}}
 private final Runnable sample=new Runnable(){public void run(){if(!enabled)return;if(left.pointer>=0||right.pointer>=0)input.nativeTouch(right.x,-right.y,-left.y,left.x,lastEvent,"NATIVE_ANDROID_POINTER_STATE_SAMPLE",pointerIds(),"HELD_POINTER_STATE");ui.postDelayed(this,50);}};
 private float axis(float delta,float radius){float dead=8*getResources().getDisplayMetrics().density;if(radius<=dead)return 0;float a=Math.abs(delta);return a<=dead?0:Math.copySign(Math.min(1,(a-dead)/(radius-dead)),delta);}
 public String mappingSnapshot(){try{org.json.JSONObject q=new org.json.JSONObject().put("version","WORKBENCH_TOUCH_8DP_V1").put("density",getResources().getDisplayMetrics().density).put("deadzoneDp",8);for(Pad p:new Pad[]{left,right})q.put(p.isLeft?"left":"right",new org.json.JSONObject().put("pointerId",p.pointer).put("rawX",p.rawX).put("rawY",p.rawY).put("width",p.getWidth()).put("height",p.getHeight()).put("radiusFraction",.62));return q.toString();}catch(Exception e){return "{}";}}
 private String pointerIds(){return "["+(left.pointer>=0?Integer.toString(left.pointer):"")+(left.pointer>=0&&right.pointer>=0?",":"")+(right.pointer>=0?Integer.toString(right.pointer):"")+"]";}
 private final class Pad extends View{int pointer=-1;float x,y,rawX,rawY;final Paint paint=new Paint(3);final boolean isLeft;Pad(Activity a,boolean l){super(a);isLeft=l;setContentDescription(l?"Cần hướng và độ cao":"Cần tiến và nghiêng");setFocusable(true);}void clear(){pointer=-1;x=0;y=0;rawX=0;rawY=0;invalidate();}
  @Override protected void onDraw(Canvas c){float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-dp(3);paint.setStyle(Paint.Style.FILL);paint.setColor(0x38212729);c.drawCircle(cx,cy,r,paint);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(1));paint.setColor(0x66ffffff);c.drawCircle(cx,cy,r,paint);c.drawLine(cx-r*.6f,cy,cx+r*.6f,cy,paint);c.drawLine(cx,cy-r*.6f,cx,cy+r*.6f,paint);paint.setStyle(Paint.Style.FILL);paint.setColor(0xddebecee);c.drawCircle(cx+x*r*.62f,cy+y*r*.62f,dp(16),paint);}
  @Override public boolean onTouchEvent(MotionEvent e){if(!enabled)return false;long lag=SystemClock.uptimeMillis()-e.getEventTime();if(lag<0||lag>200){enabled(false);return true;}lastEvent=e.getEventTime();switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:if(pointer>=0){enabled(false);return true;}pointer=e.getPointerId(e.getActionIndex());case MotionEvent.ACTION_MOVE:int at=e.findPointerIndex(pointer);if(at<0){enabled(false);return true;}float cx=getWidth()/2f,cy=getHeight()/2f;rawX=e.getX(at);rawY=e.getY(at);x=axis(rawX-cx,cx*.62f);y=axis(rawY-cy,cy*.62f);break;case MotionEvent.ACTION_POINTER_DOWN:enabled(false);return true;case MotionEvent.ACTION_POINTER_UP:if(e.getPointerId(e.getActionIndex())!=pointer)return true;case MotionEvent.ACTION_UP:case MotionEvent.ACTION_CANCEL:if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){left.clear();right.clear();input.nativeTouch(0,0,0,0,lastEvent,"NATIVE_ANDROID_POINTER_RELEASE","[]","CANCEL_ALL");post(()->enabled(false));}else{clear();if(left.pointer>=0||right.pointer>=0)input.nativeTouch(right.x,-right.y,-left.y,left.x,lastEvent,"NATIVE_ANDROID_POINTER_STATE_SAMPLE",pointerIds(),"PARTIAL_POINTER_RELEASE");else input.nativeTouch(0,0,0,0,lastEvent,"NATIVE_ANDROID_POINTER_RELEASE","[]","ALL_POINTERS_UP");if(left.pointer<0&&right.pointer<0)post(()->enabled(false));}break;default:return true;}invalidate();return true;}
 }
}
